class Solution:
    def containsPattern(self, arr: List[int], m: int, k: int) -> bool:
        n = len(arr)
        for start in range(n - m * k + 1):
            ok = True
            for j in range(1, k):
                for t in range(m):
                    if arr[start + j * m + t] != arr[start + t]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return True
        return False

