class Solution {
public:
    bool containsPattern(vector<int>& arr, int m, int k) {
        int n = arr.size();
        for (int start = 0; start + m * k <= n; ++start) {
            bool ok = true;
            for (int j = 1; j < k && ok; ++j) {
                for (int t = 0; t < m; ++t) {
                    if (arr[start + j * m + t] != arr[start + t]) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok) return true;
        }
        return false;
    }
};

