class Solution:
    def containsPattern(self, arr: List[int], m: int, k: int) -> bool:
        target = (k - 1) * m
        streak = 0
        for i in range(m, len(arr)):
            streak = streak + 1 if arr[i] == arr[i - m] else 0
            if streak >= target:
                return True
        return False

